WITH employees_by_department AS (SELECT dept_id, ROUND((100 * SUM(CASE WHEN job_title = 'Designer' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_designer, SUM(CASE WHEN job_title = 'Intern' THEN 1 ELSE 0 END) AS intern_count FROM employees GROUP BY dept_id) SELECT d.id, d.budget, ebd.pct_designer, ebd.intern_count FROM departments d LEFT JOIN employees_by_department ebd ON d.id = ebd.dept_id ORDER BY d.id DESC
